import{_ as t}from"./plugin-vue_export-helper-c27b6911.js";import{r as o,o as i,c as s,a as e,e as a,b as r,d as l}from"./app-8893173c.js";const d={},c=e("h1",{id:"customization-and-contribution",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#customization-and-contribution","aria-hidden":"true"},"#"),a(" Customization and Contribution")],-1),p=e("h2",{id:"webgal-source-code-repository",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#webgal-source-code-repository","aria-hidden":"true"},"#"),a(" WebGAL Source Code Repository")],-1),u={href:"https://github.com/OpenWebGAL/WebGAL",target:"_blank",rel:"noopener noreferrer"},h=l(`<h2 id="branch-description" tabindex="-1"><a class="header-anchor" href="#branch-description" aria-hidden="true">#</a> Branch Description</h2><div class="language-text line-numbers-mode" data-ext="text"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#F8F8F2;">main: Stable version</span></span>
<span class="line"><span style="color:#F8F8F2;">dev: WebGAL development version</span></span>
<span class="line"><span style="color:#F8F8F2;">other branches: Archives of older versions</span></span>
<span class="line"><span style="color:#F8F8F2;"></span></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="update-plan" tabindex="-1"><a class="header-anchor" href="#update-plan" aria-hidden="true">#</a> Update Plan</h2><p>See <a href="/info">WebGAL Information</a></p><h2 id="contributor-guidelines" tabindex="-1"><a class="header-anchor" href="#contributor-guidelines" aria-hidden="true">#</a> Contributor Guidelines</h2><p>If you wish to contribute to the WebGAL Terre visual editor, please refer to the <a href="terre">WebGAL Terre Contributor Guide</a></p><h3 id="regarding-the-use-of-ai" tabindex="-1"><a class="header-anchor" href="#regarding-the-use-of-ai" aria-hidden="true">#</a> Regarding the Use of AI</h3><p>AI has changed the way software is developed. While significantly increasing software development efficiency, it has also brought many challenges. When building UI, extensive use of AI often leads to issues known as &quot;AI Slop&quot;—AI-generated UIs frequently do not align with human usage habits, sometimes include meaningless explanatory text, and often suffer from layout issues such as overflow and misalignment. When writing code, AI is also prone to producing a large amount of redundant code or &quot;defensive programming&quot; code in an effort to quickly patch errors. AI also struggles to produce more concise code that is easy to read and maintain.</p><p>The WebGAL project has established some guidelines regarding the use of AI. When writing code, please comply with these guidelines:</p><ol><li><p>Humans design the architecture and implementation plan, while AI writes the code. We do not accept coding approaches where goals are simply given to AI without human involvement in the design. After AI writes the code, manual code review and testing of the relevant modules are required before submitting a PR.</p></li><li><p>AI-generated text is not allowed in Issues and PRs. Even if it is not very detailed, you only need to provide sufficient information to locate the issue or explain your intent. Overly detailed AI-generated descriptions make it harder to grasp key points and focus on truly important information.</p></li><li><p>For UI, prototype design must be completed by humans; AI can only be used for implementation. Based on our experience over several past version iterations, UIs generated directly by AI based on features are considered far below expectations.</p></li></ol><h3 id="contribution-requirements" tabindex="-1"><a class="header-anchor" href="#contribution-requirements" aria-hidden="true">#</a> Contribution Requirements</h3><p>To help us better understand and review your contribution, please note the following:</p><p><strong>Pre-Pull Request Preparation:</strong></p><ol><li><p><em>Submit an Issue First:</em> <strong>Before starting development work, please submit an Issue to discuss your ideas and design proposal</strong>. This helps avoid duplicate work, ensures your contribution aligns with the project direction, and prevents PRs from being unable to merge due to design issues.</p></li><li><p><em>RFC (Request for Comments):</em> For major changes or new features, we recommend submitting an RFC or detailed design proposal first to discuss the feasibility of the technical approach with maintainers and community members.</p></li></ol><p><strong>Code Quality Requirements:</strong></p><ol><li><p>To help us understand your code logic, we recommend adding comments to key sections.</p></li><li><p>If you add or modify functionality, please provide corresponding test methods to ensure the functionality works as expected. If you refactor code, please also provide test methods to cover the affected areas and ensure the refactoring does not introduce new issues.</p></li><li><p>When submitting a Pull Request, please briefly describe the changes you made and the reasons behind them, and reference the related Issue. This will help us understand your contribution more quickly.</p></li></ol><h3 id="starting-the-webgal-project-locally" tabindex="-1"><a class="header-anchor" href="#starting-the-webgal-project-locally" aria-hidden="true">#</a> Starting the WebGAL Project Locally</h3><p>WebGAL currently uses yarn as a package manager and yarn workspace as a monorepo manager.</p><p>If you don&#39;t have yarn, please install it using the following command:</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#50FA7B;">npm</span><span style="color:#F8F8F2;"> </span><span style="color:#F1FA8C;">install</span><span style="color:#F8F8F2;"> </span><span style="color:#F1FA8C;">yarn</span><span style="color:#F8F8F2;"> </span><span style="color:#BD93F9;">-g</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Then, execute the following command in the project root directory:</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#50FA7B;">yarn</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>to install dependencies.</p><p>This project has 3 packages, each corresponding to different functionalities:</p><table><thead><tr><th>Package Name</th><th>Content</th></tr></thead><tbody><tr><td>parser</td><td>WebGAL Parser</td></tr><tr><td>server</td><td>WebGAL Local Debug Server</td></tr><tr><td>webgal</td><td>Engine Core</td></tr><tr><td>yukimi</td><td>Planned yukimi support library</td></tr></tbody></table><h2 id="starting-the-webgal-engine-project-locally" tabindex="-1"><a class="header-anchor" href="#starting-the-webgal-engine-project-locally" aria-hidden="true">#</a> Starting the WebGAL Engine Project Locally</h2><p>You can start the development server by running the following script:</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#50FA7B;">yarn</span><span style="color:#F8F8F2;"> </span><span style="color:#F1FA8C;">dev</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>If you want to build WebGAL, use:</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#50FA7B;">yarn</span><span style="color:#F8F8F2;"> </span><span style="color:#F1FA8C;">build</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>The packaged output is located in the <code>packages/webgal/dist</code> directory.</p><h2 id="about-webgal-technology" tabindex="-1"><a class="header-anchor" href="#about-webgal-technology" aria-hidden="true">#</a> About WebGAL Technology</h2><p>WebGAL is a project of considerable scale, and diving directly into the code can be overwhelming. Therefore, here is a reference document about WebGAL technology to help you understand it.</p><p><a href="/en/tech">WebGAL Technical Introduction</a></p><p>In addition, we will also provide some documentation in some key directories of the source code to explain the principles of that module. This information will be provided in Chinese. Nowadays, large language models perform well enough in translation, so you don&#39;t have to worry if you can&#39;t read Chinese. You can try using a large language model to translate it into your language.</p><h2 id="importing-the-built-webgal-into-the-webgal-terre-editor" tabindex="-1"><a class="header-anchor" href="#importing-the-built-webgal-into-the-webgal-terre-editor" aria-hidden="true">#</a> Importing the Built WebGAL into the WebGAL Terre Editor</h2><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>After you have finished your customization, if you want to use the WebGAL editor to preview and manage resources in real time, import the build output into WebGAL Terre as a custom engine. See <a href="/en/derivative">How to use custom engine</a>. If you are developing WebGAL Terre from source, you can also replace <code>packages/terre2/assets/templates/WebGAL_Template</code> to update the built-in engine template.</p></div>`,37);function b(g,m){const n=o("ExternalLinkIcon");return i(),s("div",null,[c,p,e("p",null,[e("a",u,[a("https://github.com/OpenWebGAL/WebGAL"),r(n)])]),h])}const v=t(d,[["render",b],["__file","index.html.vue"]]);export{v as default};
